frappe.ui.form.on("Shipment", {

    refresh(frm) {

        frm.add_custom_button(__('Import From'), function () {

            const dialog = new frappe.ui.Dialog({
                title: __('Select Source'),
                fields: [
                    {
                        fieldname: 'source',
                        fieldtype: 'Select',
                        label: 'Fetch From',
                        options: [
                            'Delivery Note',
                            'Purchase Order'
                        ],
                        reqd: 1
                    }
                ],

                primary_action_label: __('Next'),

                primary_action(values) {

                    dialog.hide();

                    if (values.source === "Delivery Note") {
                        fetch_from_delivery_note(frm);
                    }

                    if (values.source === "Purchase Order") {
                        fetch_from_purchase_order(frm);
                    }

                }
            });

            dialog.show();

        });

    },

  validate(frm) {

    (frm.doc.custom_shipment_box || []).forEach(row => {

        let net = flt(row.net_weight);
        let gross = flt(row.gross_weight);

        if (net > gross) {
            frappe.throw(
                `Row ${row.idx}: Net Weight cannot be greater than Gross Weight`
            );
        }

    });

}

});


// ==========================================================
// SHIPMENT INNER BOX CHILD TABLE
// ==========================================================

frappe.ui.form.on("Shipment Box", {

    custom_shipment_box_add(frm) {
        update_inner_box_numbers(frm);
    },

    custom_shipment_box_remove(frm) {
        update_inner_box_numbers(frm);
    },

    box_template(frm, cdt, cdn) {

        const row = locals[cdt][cdn];

        if (!row.box_template) return;

        frappe.db.get_value(
            "Shipment Parcel Template",
            row.box_template,
            "weight"
        ).then(r => {

            const template_weight = flt(r.message.weight);
            const net = flt(row.net_weight);

            frappe.model.set_value(
                cdt,
                cdn,
                "gross_weight",
                net + template_weight
            );

        });

    },

    net_weight(frm, cdt, cdn) {

        const row = locals[cdt][cdn];

        if (!row.box_template) {
            frappe.model.set_value(cdt, cdn, "gross_weight", row.net_weight);
            return;
        }

        frappe.db.get_value(
            "Shipment Parcel Template",
            row.box_template,
            "weight"
        ).then(r => {

            const template_weight = flt(r.message.weight);

            frappe.model.set_value(
                cdt,
                cdn,
                "gross_weight",
                flt(row.net_weight) + template_weight
            );

        });

    }

});


// ==========================================================
// AUTO NUMBER INNER BOX (handles duplication)
// ==========================================================

function update_inner_box_numbers(frm) {

    (frm.doc.custom_shipment_box || []).forEach((row, index) => {
        row.inner_box_no = "P-" + (index + 1);
    });

    frm.refresh_field("custom_shipment_box");

}


// ==========================================================
// SHIPMENT OUTER BOX CHILD TABLE
// ==========================================================

frappe.ui.form.on("Shipment Outer Box", {

    custom_outer_box_add(frm) {
        update_outer_box_numbers(frm);
    },

    custom_outer_box_remove(frm) {
        update_outer_box_numbers(frm);
    },

    box_template(frm, cdt, cdn) {

        const row = locals[cdt][cdn];

        if (!row.box_template) return;

        frappe.db.get_value(
            "Shipment Parcel Template",
            row.box_template,
            "weight"
        ).then(r => {

            const template_weight = flt(r.message.weight);

            let inner_gross = 0;

            (frm.doc.custom_shipment_box || []).forEach(b => {

                if (b.outer_box === row.outer_box_no) {
                    inner_gross += flt(b.gross_weight);
                }

            });

            frappe.model.set_value(
                cdt,
                cdn,
                "gross_weight",
                inner_gross + template_weight
            );

        });

    },

    select_inner_boxes(frm, cdt, cdn) {

        const ob = locals[cdt][cdn];

        const dialog = new frappe.ui.Dialog({

            title: __("Select Inner Boxes"),
            size: "extra-large",

            fields: [

                {
                    fieldname: "inner_boxes",
                    fieldtype: "Table",
                    label: "Inner Boxes",
                    cannot_add_rows: true,

                    data: (frm.doc.custom_shipment_box || []).map(b => ({
                        select: 0,
                        inner_box_no: b.inner_box_no,
                        item_code: b.item_code,
                        description: b.item_description,
                        qty: b.qty,
                        gross_weight: b.gross_weight,
                        net_weight: b.net_weight
                    })),

                    fields: [

                        { fieldtype: "Check", fieldname: "select", label: "Select", in_list_view: 1 },
                        { fieldtype: "Data", fieldname: "inner_box_no", label: "Inner Box", read_only: 1, in_list_view: 1 },
                        { fieldtype: "Data", fieldname: "item_code", label: "Item", read_only: 1, in_list_view: 1 },
                        { fieldtype: "Small Text", fieldname: "description", label: "Description", read_only: 1, in_list_view: 1 },
                        { fieldtype: "Float", fieldname: "qty", label: "Qty", read_only: 1, in_list_view: 1 },
                        { fieldtype: "Float", fieldname: "gross_weight", label: "Gross Weight", read_only: 1, in_list_view: 1 },
                        { fieldtype: "Float", fieldname: "net_weight", label: "Net Weight", read_only: 1, in_list_view: 1 }

                    ]

                }

            ],

            primary_action_label: __("Update Outer Box"),

            primary_action(values) {

                const selected = (values.inner_boxes || []).filter(row => row.select);

                if (!selected.length) {
                    frappe.msgprint("Select at least one Inner Box");
                    return;
                }

                let gross = 0;
                let net = 0;

                (frm.doc.custom_shipment_box || []).forEach(b => {
                    if (b.outer_box === ob.outer_box_no) {
                        b.outer_box = "";
                    }
                });

                selected.forEach(sel => {

                    (frm.doc.custom_shipment_box || []).forEach(b => {

                        if (b.inner_box_no === sel.inner_box_no) {

                            b.outer_box = ob.outer_box_no;
                            gross += flt(b.gross_weight);
                            net += flt(b.net_weight);

                        }

                    });

                });

                frappe.model.set_value(
                    cdt,
                    cdn,
                    "inner_box",
                    selected.map(d => d.inner_box_no).join(", ")
                );

                frappe.model.set_value(cdt, cdn, "net_weight", net);

                if (ob.box_template) {

                    frappe.db.get_value(
                        "Shipment Parcel Template",
                        ob.box_template,
                        "weight"
                    ).then(r => {

                        let template_weight = flt(r.message.weight);

                        frappe.model.set_value(
                            cdt,
                            cdn,
                            "gross_weight",
                            gross + template_weight
                        );

                    });

                } else {

                    frappe.model.set_value(cdt, cdn, "gross_weight", gross);

                }

                frm.refresh_field("custom_shipment_box");
                frm.refresh_field("custom_outer_box");

                dialog.hide();

            }

        });

        dialog.show();

    }

});


