function fetch_from_delivery_note(frm) {

    if (!frm.doc.delivery_customer) {
        frappe.msgprint(__('Please select Delivery Customer first'));
        return;
    }

    new frappe.ui.form.MultiSelectDialog({
        doctype: "Delivery Note",
        target: frm,

        setters: {
            customer: frm.doc.delivery_customer,
            posting_date: null
        },

        add_filters_group: 1,
        date_field: "posting_date",

        get_query() {
            return {
                filters: {
                    docstatus: 1,
                    customer: frm.doc.delivery_customer
                }
            };
        },

        action(selections) {

            if (!selections.length) {
                frappe.msgprint("Please select Delivery Note");
                return;
            }

            let delivery_note = selections[0];

            frappe.call({
                method: "Get Delivery Note Items",
                args: {
                    delivery_note: delivery_note
                },
                callback: function(r) {

                    if (!r.message || !r.message.length) {
                        frappe.msgprint(__('No items found'));
                        return;
                    }

                    let items = sort_items_by_creation(r.message);

                    open_items_dialog(frm, items, "Delivery Note", delivery_note);

                }
            });

        }
    });

}
