        add_filters_group: 1,
        date_field: "transaction_date",

        get_query() {
            return {
                filters: {
                    docstatus: 1,
                    supplier: frm.doc.pickup_supplier
                }
            };
        },

        action(selections) {

            if (!selections.length) {
                frappe.msgprint(__('Please select Purchase Order'));
                return;
